<div class="modal fade glass-modal" id="editHQModal" tabindex="-1" aria-labelledby="editHQLabel" aria-hidden="true"><div class="modal-dialog modal-dialog-centered modal-dialog-scrollable modal-lg"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title fw-bold" id="editHQLabel"><i class="bi bi-pencil-square txt-neon-cyan me-2"></i> Edit HQ</h5><p class="text-white-50 small mb-0 mt-1">Update HQ and owner details in the live database.</p></div><button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><form action="hq_update_action(M).php" method="POST"><input type="hidden" name="headquarter_id" id="editHQId"><input type="hidden" name="return_to" value="view_hq_and_user_account(M).php"><div class="modal-body d-flex flex-column gap-3"><div class="manage-hq-note text-white-50 small"><span class="text-danger">*</span> Changing the owner email also updates the linked HQ account email.</div><div><label class="form-label text-white-50 small" for="editHqName">Company / HQ Name <span class="text-danger">*</span></label><input id="editHqName" type="text" name="hq_name" class="form-control glass-input" maxlength="255" required></div><div><label class="form-label text-white-50 small" for="editLogo">Company Logo URL / Storage Path <span class="text-danger">*</span></label><input id="editLogo" type="text" name="company_logo" class="form-control glass-input" maxlength="255" required></div><div class="row g-3"><div class="col-12 col-md-6"><label class="form-label text-white-50 small" for="editOwnerName">Owner Name <span class="text-danger">*</span></label><input id="editOwnerName" type="text" name="owner_name" class="form-control glass-input" maxlength="225" required></div><div class="col-12 col-md-6"><label class="form-label text-white-50 small" for="editOwnerEmail">Owner Email <span class="text-danger">*</span></label><input id="editOwnerEmail" type="email" name="owner_email" class="form-control glass-input" maxlength="225" required></div></div><div><label class="form-label text-white-50 small" for="editContact">Contact Number <span class="text-danger">*</span></label><input id="editContact" type="text" name="contact_number" class="form-control glass-input" maxlength="50" required></div><div><label class="form-label text-white-50 small" for="editRegion">Regional Headquarters Office <span class="text-danger">*</span></label><select id="editRegion" name="region" class="form-select glass-select" required><option value="">Select region</option><option value="yangon">Yangon Region</option><option value="mandalay">Mandalay Region</option><option value="naypyidaw">Naypyidaw</option></select></div><div><label class="form-label text-white-50 small" for="editAddress">Physical Address Details <span class="text-danger">*</span></label><textarea id="editAddress" name="address" rows="3" maxlength="220" class="form-control glass-input" required></textarea></div><div><label class="form-label text-white-50 small" for="editLicense">Business License <span class="text-danger">*</span></label><input id="editLicense" type="text" name="business_license" class="form-control glass-input" maxlength="255" required></div><div><label class="form-label text-white-50 small" for="editExpire">License Expiry Date <span class="text-danger">*</span></label><input id="editExpire" type="date" name="expire_at" min="<?= date('Y-m-d') ?>" class="form-control glass-input" required></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary rounded-3 text-white-50" data-bs-dismiss="modal">Cancel</button><button type="submit" class="btn btn-neon">Save HQ Changes</button></div></form></div></div></div>

<?php $moderatorActiveNav = 'view_hq'; include __DIR__ . '/includes/moderator_offcanvas.php'; ?><footer class="text-white-50 text-center py-4 mt-5 small">&copy; 2026 Map &amp; Pump | All Rights Reserved</footer><?php include __DIR__ . '/includes/moderator_footer_scripts.php'; ?>
<script>
document.addEventListener('DOMContentLoaded', () => {
    const detailModal = new bootstrap.Modal(document.getElementById('hqDetailsModal'));
    const actionModal = new bootstrap.Modal(document.getElementById('accountActionModal'));
    const detailsBody = document.getElementById('hqDetailsBody');
    let currentHQDetails = null;
    const esc = value => String(value ?? '').replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[character]));
    const date = value => value ? new Date(String(value).replace(' ', 'T')).toLocaleString() : 'Not available';
    const removeUserSections = () => { detailsBody.querySelectorAll('h6, .mod-detail-label').forEach(heading => { if (/linked\s+accounts?/i.test(heading.textContent || '')) { heading.nextElementSibling?.remove(); heading.remove(); } }); };
    new MutationObserver(removeUserSections).observe(detailsBody, {childList:true, subtree:true});
    document.querySelectorAll('.js-view-hq').forEach(button => button.addEventListener('click', async event => {
        event.preventDefault(); detailsBody.innerHTML = '<div class="text-center text-white-50 py-5"><span class="spinner-border spinner-border-sm me-2"></span>Loading HQ details...</div>'; detailModal.show();
        try { const response = await fetch('hq_details(M).php?id=' + encodeURIComponent(button.dataset.hqId)); const payload = await response.json(); if (!response.ok || !payload.success) throw new Error(payload.message || 'Unable to load HQ details.'); const h = payload.hq; currentHQDetails = h; const accounts = payload.accounts || []; const actions = payload.actions || []; detailsBody.innerHTML = '<div class="row g-4"><div class="col-12 col-md-6"><div class="mod-detail-label">Company</div><div class="mod-detail-value mb-3">'+esc(h.company_name)+'</div><div class="mod-detail-label">Location</div><div class="mod-detail-value mb-3">'+esc(h.location)+'</div><div class="mod-detail-label">Contact / Email</div><div class="mod-detail-value mb-3">'+esc(h.contact_number)+'<br>'+esc(h.headquarter_email)+'</div><div class="mod-detail-label">Owner</div><div class="mod-detail-value mb-3">'+esc(h.owner_name || 'Not available')+'<br>'+esc(h.owner_email || h.headquarter_email || 'Not available')+'</div><div class="mod-detail-label">License</div><div class="mod-detail-value">'+esc(h.business_license)+'<br>Expires: '+esc(date(h.expire_at))+'</div></div><div class="col-12 col-md-6"><div class="mod-detail-label">Created</div><div class="mod-detail-value mb-3">'+esc(date(h.created_at))+'</div><div class="mod-detail-label">Linked Accounts</div><div class="table-responsive"><table class="table mod-modal-table table-sm"><thead><tr><th>Username</th><th>Status</th></tr></thead><tbody>'+ (accounts.length ? accounts.map(a => '<tr><td>'+esc(a.username)+'<br><small>'+esc(a.email)+'</small></td><td>'+esc(a.status)+'</td></tr>').join('') : '<tr><td colspan="2" class="text-white-50">No linked accounts.</td></tr>') +'</tbody></table></div></div><div class="col-12"><div class="mod-detail-label mb-2">Action History</div>'+ (actions.length ? actions.map(a => '<div class="border-top border-white border-opacity-10 py-2"><span class="text-danger">'+esc(a.action_type)+'</span> · '+esc(date(a.created_at))+'<br><span class="text-white-50">'+esc(a.reason)+'</span></div>').join('') : '<div class="text-white-50">No suspend/remove history.</div>') +'</div></div>'; } catch (error) { detailsBody.innerHTML = '<div class="alert alert-danger">'+esc(error.message)+'</div>'; }
    }));
    document.querySelectorAll('.js-account-action').forEach(button => button.addEventListener('click', event => { event.preventDefault(); document.getElementById('actionHQId').value = button.dataset.hqId || ''; document.getElementById('actionHQName').textContent = button.dataset.hqName || 'Selected HQ'; document.getElementById('actionReason').value = ''; actionModal.show(); }));
    document.querySelectorAll('.js-edit-hq-details').forEach(button => button.addEventListener('click', () => {
        const h = currentHQDetails || {};
        const location = String(h.location || '');
        const parts = location.split(/\s+(?:—|-)\s+/);
        const regionRaw = String(parts[0] || '').toLowerCase().replace(/\s+region$/, '').trim();
        const address = parts.length > 1 ? parts.slice(1).join(' - ') : location;
        document.getElementById('editHQId').value = h.headquarter_id || '';
        document.getElementById('editHqName').value = h.company_name || '';
        document.getElementById('editLogo').value = h.company_logo || '';
        document.getElementById('editContact').value = h.contact_number || '';
        document.getElementById('editOwnerName').value = h.owner_name || '';
        document.getElementById('editOwnerEmail').value = h.owner_email || h.headquarter_email || '';
        document.getElementById('editRegion').value = regionRaw;
        document.getElementById('editAddress').value = address;
        document.getElementById('editLicense').value = h.business_license || '';
        document.getElementById('editExpire').value = h.expire_at ? String(h.expire_at).slice(0, 10) : '';
    }));
});
</script>
</body>
</html>
